<section class="container page-section"><div class="row justify-content-center"><div class="col-lg-8"><a class="back-link mb-3" href="<?php echo site_url($quote['type']==='arena'?'belajar/arena':'latihan/mandiri'); ?>">Ruang belajar</a><div class="learning-hero mb-4"><p class="eyebrow">Kredit untuk pilihanmu</p><h1 class="h2"><?php echo html_escape($quote['title']); ?></h1><p class="h4 mb-0"><?php echo (int)$quote['price']; ?> kredit<?php echo !$quote['enabled']?' · draft':''; ?></p></div><div class="feature-card"><p><?php echo html_escape($quote['detail']); ?></p><?php if($included): ?><p class="alert alert-success">Akses akun Anda sudah termasuk Platinum Selamanya, tanpa potongan kredit dan tanpa kuota harian latihan. Batas waktu serta syarat progres tetap berlaku.</p><?php endif; ?><?php if($error): ?><div class="alert alert-warning" role="alert"><?php echo html_escape($error); ?></div><?php endif; ?><?php if($current_user['account_kind']==='child'): ?><p class="alert alert-info"><?php echo $included?'Akunmu sudah memiliki akses. Silakan kembali ke modul untuk mulai belajar.':'Minta orang tua membuka akses untuk akunmu. Akun anak tidak dapat memotong saldo atau melakukan pembayaran.'; ?></p><?php elseif(!$quote['enabled']): ?><p class="alert alert-info">Harga ini masih draft. Penukaran belum diaktifkan oleh pemilik; tidak ada saldo yang dipotong.</p><?php else: ?><?php echo form_open('latihan/buka/'.$quote['type'].'/'.$quote['id']); ?><input type="hidden" name="version" value="<?php echo html_escape($quote['version']); ?>"><label class="form-label" for="learner_id">Penerima akses</label><select class="form-select mb-3" id="learner_id" name="learner_id" required><?php foreach($beneficiaries as $b): ?><option value="<?php echo (int)$b['id']; ?>"><?php echo html_escape($b['display_name']); ?><?php echo $owned[$b['id']]?' · sudah dimiliki':''; ?></option><?php endforeach; ?></select><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="confirm" value="1" required><span class="form-check-label">Saya memeriksa penerima dan menyetujui pemotongan <?php echo (int)$quote['price']; ?> kredit. Akses yang sudah dimiliki tidak ditagih lagi.</span></label><button class="btn btn-primary" type="submit">Tukar kredit</button><a class="btn btn-outline-primary" href="<?php echo site_url('akun/kredit?environment=production'); ?>">Lihat saldo</a><?php echo form_close(); ?><?php endif; ?><?php if($beneficiaries): ?><h2 class="h5 mt-4">Status akses</h2><ul><?php foreach($beneficiaries as $b): ?><li><?php echo html_escape($b['display_name']); ?>: <?php echo $owned[$b['id']]?'sudah dibuka':'belum dibuka'; ?></li><?php endforeach; ?></ul><?php endif; ?><?php if(!empty($quote['packs'])): ?><h2 class="h5 mt-4">Set yang termasuk</h2><ul><?php foreach($quote['packs'] as $pack): ?><li><a href="<?php echo site_url('belajar/arena/pilih/'.$pack['slug']); ?>"><?php echo html_escape($pack['title']); ?></a><?php echo !$pack['enabled']?' (dijeda)':''; ?></li><?php endforeach; ?></ul><?php endif; ?></div></div></div></section>
